    if (myvendor_is_factory()) {
#ifdef CONFIG_MYVENDOR_FACTORY_MODE
        return lv_pm_open_page_msg((lv_pm_id)BICYCLE_PM_ID_FACTORY, NULL);
#else
        return -1;
#endif
    }

    map = live_map_page_def();

