1056	static bool pump_tile_dirty(const vmap_view_t * view, int32_t tx, int32_t ty)
1057	{
1058	    const int32_t tile_size = 256;
1059	    int32_t x1;
1060	    int32_t y1;
1061	    int32_t x2;
1062	    int32_t y2;
1063	    uint8_t i;
1064	
1065	    if (!view || view->pump_dirty_n == 0) {
1066	        return true;
1067	    }
1068	
1069	    x1 = (int32_t)lround((tx * tile_size - view->pump_cx) * view->scale
1070	        + view->w / 2.0);
1071	    y1 = (int32_t)lround((ty * tile_size - view->pump_cy) * view->scale
1072	        + view->h / 2.0);
1073	    x2 = (int32_t)lround(x1 + 256.0 * view->scale);
1074	    y2 = (int32_t)lround(y1 + 256.0 * view->scale);
1075	
1076	    for (i = 0; i < view->pump_dirty_n; i++) {
1077	        if (pump_rects_overlap(x1, y1, x2, y2,
1078	                view->pump_dirty_x1[i], view->pump_dirty_y1[i],
1079	                view->pump_dirty_x2[i], view->pump_dirty_y2[i])) {
1080	            return true;
1081	        }
1082	    }
1083	    return false;
1084	}
