1086	static bool pump_advance(vmap_view_t * view)
1087	{
1088	    view->pump_ty--;
1089	    if (view->pump_ty < view->pump_ty_min) {
1090	        view->pump_tx--;
1091	        view->pump_ty = view->pump_ty_max;
1092	    }
1093	    return view->pump_tx >= view->pump_tx_min;
1094	}
