1096	static void render_begin(vmap_view_t * view, bool reset_view, bool force_clear)
1097	{
1098	    vmap_canvas_t canvas;
1099	    const double origin_lon = reset_view ? view->lon : view->render_lon;
1100	    const double origin_lat = reset_view ? view->lat : view->render_lat;
1101	    int32_t sx;
1102	    int32_t sy;
1103	    bool scrolled = false;
1104	
1105	    /* fopen/.vpk index belongs on the first pump tick, not GNSS/REC/set_view. */
1106	
1107	    dvfs_map_busy(true);
1108	    view->pump_dirty_n = 0;
1109	    sx = (view->last_pan_px == INT32_MIN) ? (int32_t)lround(view->pan_dx)
1110	                                         : view->last_pan_px;
1111	    sy = (view->last_pan_py == INT32_MIN) ? (int32_t)lround(view->pan_dy)
1112	                                         : view->last_pan_py;
1113	
1114	    if (reset_view) {
1115	        /*
1116	         * A hidden page can jump much farther than the last on-screen pan.
1117	         * Derive the pixel migration from the two geographic origins instead
1118	         * of trusting last_pan_px.  Otherwise a 1 km jump with a 14 px old pan
1119	         * scrolls only 14 px, then marks the whole interior as the new origin.
1120	         */
1121	        if (!force_clear && view->render_rev > 0
1122	            && view->paint_zoom == view->zoom
1123	            && view->paint_scale == view->scale) {
1124	            int old_x = 0;
1125	            int old_y = 0;
1126	            int new_x = 0;
1127	            int new_y = 0;
1128	
1129	            vmap_latlong_to_pixel(view->render_lat, view->render_lon,
1130	                view->zoom, &old_x, &old_y);
1131	            vmap_latlong_to_pixel(origin_lat, origin_lon,
1132	                view->zoom, &new_x, &new_y);
1133	            sx = (int32_t)lround((new_x - old_x) * view->scale);
1134	            sy = (int32_t)lround((new_y - old_y) * view->scale);
1135	        }
1136	
1137	        bool can_scroll = !force_clear && view->render_rev > 0
1138	            && view->paint_zoom == view->zoom
1139	            && view->paint_scale == view->scale
1140	            && (sx != 0 || sy != 0)
1141	            && sx > -view->w && sx < view->w
1142	            && sy > -view->h && sy < view->h;
1143	
1144	        view->render_lon = origin_lon;
1145	        view->render_lat = origin_lat;
1146	        view_canvas(view, &canvas, false);
1147	        if (can_scroll) {
1148	            vmap_render_scroll(&canvas, sx, sy, vmap_style_bg565());
1149	            pump_dirty_from_scroll(view, sx, sy);
1150	            vmap_label_retained_scroll(&view->label_col, sx, sy,
1151	                VMAP_RENDER_DIRTY_MAX, &view->pump_dirty_n,
1152	                view->pump_dirty_x1, view->pump_dirty_y1,
1153	                view->pump_dirty_x2, view->pump_dirty_y2);
1154	            scrolled = true;
1155	            lv_obj_invalidate(view->canvas);
1156	        } else {
1157	            vmap_render_clear(&canvas, vmap_style_bg565());
1158	            vmap_label_retained_reset(&view->label_col);
1159	        }
1160	
1161	        view->pan_dx = 0.0;
1162	        view->pan_dy = 0.0;
1163	        view->last_pan_px = INT32_MIN;
1164	        view->last_pan_py = INT32_MIN;
1165	        vmap_view_apply_canvas_pos(view, 0.0, 0.0);
1166	    } else {
1167	        /* keep-pan redraw repaints every base tile, erasing all baked labels. */
1168	        vmap_label_retained_reset(&view->label_col);
1169	    }
1170	
1171	    vmap_label_collector_reset(&view->label_col);
1172	    view->label_col.clip_n = 0;
1173	    vmap_label_collector_set_focus(&view->label_col,
1174	        view->w / 2 + (int32_t)lround(view->pan_dx),
1175	        view->h / 2 + (int32_t)lround(view->pan_dy));
1176	
1177	    vmap_latlong_to_pixel(origin_lat, origin_lon, view->zoom,
1178	        &view->pump_cx, &view->pump_cy);
1179	    tile_range(view->pump_cx, view->pump_cy, view->w, view->h, view->scale, 1,
1180	        &view->pump_tx_min, &view->pump_ty_min,
1181	        &view->pump_tx_max, &view->pump_ty_max);
1182	    view->pump_tx = view->pump_tx_max;
1183	    view->pump_ty = view->pump_ty_max;
1184	    view->pump_phase = 1;
1185	    view->pump_need_region = 1;
1186	
1187	    if (scrolled) {
1188	        syslog(LOG_NOTICE,
1189	            "[map] rebase scroll=%d,%d dirty=%u labels=%d z=%d",
1190	            (int)sx, (int)sy, (unsigned)view->pump_dirty_n,
1191	            (int)view->label_col.retained_count, view->zoom);
1192	    }
1193	}
